                        return False
                elif char == 'b':
                    if not (dfs(neighbor, 'a', assignment) or dfs(neighbor, 'c', assignment)):
                        return False
                elif char == 'c':
                    if not dfs(neighbor, 'b', assignment):
                        return False
            else:
